INSERT INTO recipe_step (recipe_id, step_order, description) VALUES
  (11,1,'손질된 새우를 끓는 물에 데쳐 건진다.'),(11,2,'연두부, 달걀, 생크림, 설탕에 녹인 무염버터를 믹서에 넣고 간 뒤 새우를 함께 섞어 그릇에 담는다.'),(11,3,'시금치를 잘게 다져 그릇에 뿌리고 찜기에 넣어 중간 불에서 10분 정도 찐다.'),
  (12,1,'김치, 베이컨, 스팸, 소시지, 양파, 두부, 무는 두께 0.5cm로 썬다.'),(12,2,'다시마와 물을 끓여 다시마물을 만든다.'),(12,3,'냄비에 소시지, 베이컨, 두부, 스팸, 무, 김치, 다시마물 300g을 넣어 끓인 후 저염된장, 양파, 대파, 다진 마늘, 떡국 떡을 넣고 재료가 다 익으면 홍고추와 청양고추를 넣어 완성한다.'),
  (13,1,'감자는 믹서에 갈고 양배추는 채 썰고 돼지고기, 당근, 청양고추, 두부는 다진다.'),(13,2,'준비해 둔 재료를 모두 섞고 부침가루와 달걀을 넣어 반죽한다.'),(13,3,'가열된 팬에 기름을 두르고 반죽을 부어 앞뒤로 노릇하게 굽고 소스를 곁들인다.'),
  (14,1,'발사믹식초, 화이트와인, 다진 유자청 건더기를 넣고 졸여 소스를 만들고 대구를 손질하여 포를 뜬다.'),(14,2,'대파, 청파프리카, 홍파프리카, 황파프리카를 채 썬다.'),(14,3,'대구포에 밀가루를 묻혀 파프리카, 팽이버섯을 넣고 말아 미나리로 묶은 뒤 쪄서 소스를 뿌리고 대파를 올려 완성한다.'),
  (15,1,'양파와 마늘을 다져 볶다가 토마토 과육과 설탕, 바질을 넣고 고추장을 섞어 토마토 소스를 만든다.'),(15,2,'가지, 양송이버섯, 애호박, 사과는 5mm 두께로 썰고 살라미는 끓는 물에 데친다.'),(15,3,'오븐용 팬에 토마토 소스를 깔고 채소와 살라미를 겹치게 올린 뒤 180°C 오븐에서 30분 구워 완성한다.'),
  (16,1,'끓는 물에 배춧잎을 데친다.'),(16,2,'당근, 호박, 표고버섯, 양파는 입자 있게 다진다.'),(16,3,'돼지고기를 썰어 불린 쌀, 다진 야채와 함께 밥을 짓는다.'),(16,4,'데친 배춧잎에 지어 놓은 밥을 올려 돌돌 만다.'),(16,5,'말아 놓은 배춧잎을 부추로 묶는다.'),(16,6,'찜통에 김이 오르면 배추롤을 넣고 약 5분 정도 찐다.'),
  (17,1,'대추는 돌려 깍아 씨를 제거하고 곱게 다진다.'),(17,2,'다진 소고기와 돼지고기에 대추, 소금, 후춧가루를 넣고 치댄다.'),(17,3,'애호박, 단호박, 파프리카는 입자 있게 썰어 고기에 넣고 잘 치댄다.'),(17,4,'양송이는 편으로 썰어 팬에 익히고 인삼은 볶아 잘게 썰어 고기 반죽에 넣는다.'),(17,5,'재료가 골고루 섞인 반죽을 갈비 모양으로 만든다.'),(17,6,'팬에 떡갈비를 굽고 접시에 배춧잎을 깔고 익힌 양송이를 올린 뒤 떡갈비를 담아 완성한다.'),
  (18,1,'된장에 두부를 넣고 골고루 섞는다.'),(18,2,'표고버섯과 마늘은 함께 갈아 둔다.'),(18,3,'미역은 충분히 불린다.'),(18,4,'냄비에 황태채와 갈아 둔 표고버섯, 마늘을 넣고 은근히 끓여 육수를 만든다.'),(18,5,'곤약은 납작납작하게 썰어 끓는 물에 데친다.'),(18,6,'육수에서 황태를 건져 두부된장과 함께 갈아 육수에 붓고 미역, 곤약, 들깨가루를 넣고 20분 끓인 후 액젓으로 간을 맞춰 완성한다.'),
  (19,1,'훈제오리 가슴살을 얇게 슬라이스한다.'),(19,2,'슬라이스한 훈제오리를 팬에 앞뒤로 굽는다.'),(19,3,'양파는 채 썰어 찬물에 담갔다가 건진다.'),(19,4,'레디쉬는 얇게 채 썰어 찬물에 담갔다가 건진다.'),(19,5,'먹기 직전에 발사믹 소스를 준비한다.'),(19,6,'접시에 훈제오리, 양파채, 레디쉬, 블루베리를 담고 발사믹 소스를 뿌려 완성한다.'),
  (20,1,'훈제오리 가슴살을 올리브오일, 로즈마리, 후춧가루로 마리네이드한다.'),(20,2,'새송이버섯은 편으로 썰어 팬에 노릇하게 굽는다.'),(20,3,'오렌지는 원형으로 슬라이스한다.'),(20,4,'땅콩과 파슬리는 입자 있게 다진다.'),(20,5,'마리네이드한 오리 고기를 팬에 구워 접시에 담는다.'),(20,6,'유자청에 다진 땅콩과 파슬리를 넣어 소스를 만들고 오리고기 사이에 오렌지 슬라이스를 끼운 뒤 유자청 소스를 올려 완성한다.'),
  (21,1,'찹쌀은 깨끗이 씻어 30분 정도 불린다.'),(21,2,'불린 찹쌀을 냄비에 넣고 질게 밥을 한다.'),(21,3,'닭가슴살은 넓게 펴서 소금, 후춧가루를 뿌린다.'),(21,4,'호박잎과 미나리는 끓는 물에 살짝 데치고 대추는 씨를 제거하고 인삼은 채를 썰어 둔다.'),(21,5,'데친 호박잎에 닭가슴살을 올린다.'),(21,6,'닭가슴살 위에 찹쌀밥과 야채, 대추를 올려 돌돌 말고 약 20분 더 쪄 완성한다.');
